/**
 * Generated GraphQL types and hooks for Mirai App
 *
 * This package is generated by @mirai-app/frameworks using graphql-codegen.
 * Do not edit these files directly - they will be overwritten on regeneration.
 *
 * ## Usage
 *
 * ```typescript
 * import { GetUserDocument, useGetUserQuery } from "@mirai-app/graphql-client";
 * import type { User, Trip } from "@mirai-app/graphql-client/types";
 *
 * // In React component:
 * const [{ data, fetching, error }] = useGetUserQuery({ variables: { id: "123" } });
 * ```
 *
 * ## Regeneration
 *
 * From the monorepo root:
 * ```bash
 * bun run --filter=@mirai-app/frameworks sync:schema
 * ```
 */

// =============================================================================
// Type Exports
// =============================================================================

export * from "./generated/types.js";
export * from "./generated/operations.js";

// =============================================================================
// Urql Hooks (React)
